      pt: "Uma cidade histórica no leste, conhecida pelos seus sítios arqueológicos da era budista e doces deliciosos.",
      fr: "Une ville historique à l'est, connue pour ses sites archéologiques de l'ère bouddhiste et ses délicieuses confiseries.",
