     image: "/poi-images/comilla-cities-v2.webp",
    descriptionAdvanced: {
      de: "Comilla, offiziell als Kumilla bekannt, liegt im Osten von Bangladesch am Fluss Gumti und ist eine Stadt von großer historischer und archäologischer Bedeutung. Die Region war im 7. und 8. Jahrhundert ein blühendes Zentrum der buddhistischen Zivilisation, was heute durch die Ruinen von Mainamati und Shalban Vihara belegt wird. Während der britischen Kolonialzeit entwickelte sich Comilla zu einem wichtigen Verwaltungs- und Bildungszentrum. Die Stadt ist weltweit bekannt für die Gründung der Bangladesh Academy for Rural Development (BARD) im Jahr 1959, die innovative Modelle für die ländliche Entwicklung hervorbrachte. Wirtschaftlich ist Comilla für die Produktion von Khadi-Stoffen und seine berühmten Rosogolla-Süßigkeiten bekannt. Geografisch liegt die Stadt nahe der indischen Grenze zum Bundesstaat Tripura, was sie zu einem wichtigen Knotenpunkt für den grenzüberschreitenden Handel und Verkehr macht. Die Comilla-Region zeichnet sich zudem durch ihre sanften Hügelketten aus, die eine Ausnahme im flachen Delta bilden.",
      hu: "Comilla, hivatalos nevén Kumilla, Banglades keleti részén, a Gumti-folyó partján fekszik, és nagy történelmi, valamint régészeti jelentőségű város. A régió a 7. és 8. században a buddhista civilizáció virágzó központja volt, amit ma a Mainamati és Shalban Vihara romjai bizonyítanak. A brit gyarmati időszakban Comilla fontos közigazgatási és oktatási központtá fejlődött. A város világszerte ismert a Bangladesi Vidékfejlesztési Akadémia (BARD) 1959-es alapításáról, amely innovatív modelleket dolgozott ki a vidéki közösségek számára. Gazdaságilag Comilla a Khadi szövetek gyártásáról és híres Rosogolla édességeiről nevezetes. Földrajzilag a város közel fekszik az indiai Tripura állam határához, ami fontos csomóponttá teszi a határon átnyúló kereskedelemben. A Comilla-régiót emellett szelíd dombok jellemzik, amelyek ritkaságnak számítanak a sík deltavidéken.",
      ro: "Comilla, cunoscut oficial sub numele de Kumilla, este situat în estul Bangladeshului, pe râul Gumti, fiind un oraș de o mare importanță istorică și arheologică. Regiunea a fost un centru înfloritor al civilizației budiste în secolele VII și VIII, fapt dovedit astăzi de ruinele de la Mainamati și Shalban Vihara. În timpul erei coloniale britanice, Comilla s-a dezvoltat ca un centru administrativ și educațional major. Orașul este recunoscut la nivel mondial pentru înființarea Academiei din Bangladesh pentru Dezvoltare Rurală (BARD) în 1959, care a creat modele inovatoare pentru comunitățile rurale. Din punct de vedere economic, Comilla este faimos pentru producția de țesături Khadi și pentru dulciurile sale Rosogolla. Geografic, orașul se află aproape de granița cu statul indian Tripura, ceea ce îl transformă într-un nod important pentru comerțul transfrontalier. Regiunea Comilla se remarcă, de asemenea, prin dealurile sale line, o excepție în peisajul plat al deltei.",
      en: "Comilla, officially known as Kumilla, is located in eastern Bangladesh on the Gumti River and is a city of immense historical and archaeological significance. The region was a thriving center of Buddhist civilization during the 7th and 8th centuries, evidenced today by the ancient ruins of Mainamati and Shalban Vihara. During the British colonial era, Comilla evolved into an important administrative and educational hub. The city gained international recognition for the establishment of the Bangladesh Academy for Rural Development (BARD) in 1959, which pioneered innovative models for rural upliftment. Economically, Comilla is renowned for its hand-woven Khadi fabrics and its famous Rosogolla sweets. Geographically, its proximity to the Indian state of Tripura makes it a vital transit point for cross-border trade. The Comilla region is also distinguished by its low hills, which provide a rare variation in the country's flat deltaic landscape.",
      es: "Esta ciudad cerca de la frontera con la India alberga antiguas ruinas budistas y posee una importante base militar. Esto la convierte en uno de los puntos característicos de Bangladés en el delta del Ganges-Brahmaputra, en el golfo de Bengala y en los alrededores de los manglares de Sundarbans, ofreciendo una visión de la cultura bengalí, el monzón y la identidad regional. Situada en el estado de Bangladés, en el sur de Asia. Región caracterizada por el delta del Ganges-Brahmaputra y el golfo de Bengala. Clima monzónico tropical con marcadas estaciones lluviosa y seca. Accesible a través de la red de carreteras y el extenso sistema fluvial del delta.",
      pt: "Esta cidade perto da fronteira com a Índia alberga ruínas budistas antigas e possui uma importante base militar. Isto torna o local num dos pontos característicos do Bangladexe no delta do Ganges-Brahmaputra, no golfo de Bengala e na envolvente dos mangais de Sundarbans, oferecendo uma visão da cultura bengali, da monção e da identidade regional. Localizada no estado do Bangladexe, no sul da Ásia. Região caracterizada pelo delta do Ganges-Brahmaputra e pelo golfo de Bengala. Clima tropical de monção com estações chuvosa e seca distintas. Acessível através da rede rodoviária e do extenso sistema fluvial do delta.",
      fr: "Cette ville proche de la frontière indienne abrite d'anciennes ruines bouddhistes et possède une base militaire importante. Cela fait de ce lieu l'un des points caractéristiques du Bangladesh dans le delta du Gange-Brahmapoutre, dans le golfe du Bengale et dans les environs des mangroves des Sundarbans, offrant un aperçu de la culture bengalie, de la mousson et de l'identité régionale. Située dans l'État du Bangladesh, en Asie du Sud. Région marquée par le delta du Gange-Brahmapoutre et le golfe du Bengale. Climat de mousson tropicale avec des saisons des pluies et des saisons sèches marquées. Accessible via le réseau routier et le vaste système fluvial du delta.",
    },
