      fr: ["Plus vieille ville du Bangladesh (proche de Mahasthangarh)", "Célèbre pour son yaourt sucré spécial (Mishti Doi)", "Plus importante place commerciale pour les produits agricoles", "Centre historique de la civilisation Pundra"],
