      pt: ["Capital cultural do Bangladesh", "Abriga o santuário do místico Lalon Shah", "Localização do Shilaidaha Kuthibari de Tagore", "Centro de destaque da música folclórica e filosofia"],
      fr: ["Capitale culturelle du Bangladesh", "Abrite le sanctuaire du mystique Lalon Shah", "Lieu où se trouve la résidence Shilaidaha Kuthibari de Tagore", "Centre majeur pour la musique folklorique et la philosophie"],
