      de: ["Gilt als kulturelle Hauptstadt von Ostbangladesch", "Großes Zentrum für Erdgasproduktion", "Geburtsort vieler berühmter Musiker und Gelehrter", "Wichtiges Zentrum für Weberei und Handwerk"],
