      pt: ["Situada na extremidade ocidental da ponte Jamuna", "Importante centro para o comércio de juta e têxteis", "Historicamente significativa pela tecelagem manual", "Importante nó de transportes no rio Jamuna"],
      fr: ["Située à l'extrémité ouest du pont Jamuna", "Centre important pour le commerce du jute et des textiles", "Historiquement importante pour le tissage à la main", "Important carrefour de transport sur le fleuve Jamuna"],
