      pt: ["Situada na margem ocidental do rio Brahmaputra, a cidade destaca-se pelo seu artesanato.", "Localiza-se no estado do Bangladesh, no sul da Ásia.", "Região caracterizada pelo delta do Ganges-Brahmaputra e pelo Golfo de Bengala.", "Clima de monção tropical com estações de chuva e seca bem definidas.", "Acessível por estrada e através do complexo sistema fluvial do delta.", "Ligada ao património da cultura bengali e à Bengala histórica.", "Os Sundarbans, o maior manguezal do mundo, moldam o sul do país.", "Economia fortemente baseada nas indústrias têxtil, de juta e de navegação."],
      fr: ["Située sur la rive ouest du Brahmapoutre, cette ville est riche en traditions artisanales.", "Localisée dans l'État sud-asiatique du Bangladesh.", "Région façonnée par le delta du Gange-Brahmapoutre et le golfe du Bengale.", "Climat de mousson tropicale avec des saisons sèches et humides marquées.", "Accessible par le réseau routier et le vaste système fluvial du delta.", "Liée à l'héritage de la culture bengalie et du Bengale historique.", "Les Sundarbans, plus grande forêt de mangroves au monde, marquent le sud du pays.", "Économie dominée par les industries du textile, du jute et de la navigation."],
