      pt: ["Região conhecida como o celeiro do país pela sua produção de arroz.", "Localizada no estado do Bangladesh, no sul da Ásia.", "Geografia marcada pelo delta do Ganges-Brahmaputra e pelo Golfo de Bengala.", "Clima de monção tropical com estações húmidas e secas definidas.", "Ligada por estradas e através dos rios do delta.", "Sede de importantes vestígios da cultura e do passado de Bengala.", "Os manguezais de Sundarbans definem o ecossistema do sul.", "Economia impulsionada pela agricultura, têxteis e comércio de juta."],
