      fr: ["Ville côtière dotée d'une culture et d'un dialecte propres.", "Située dans l'État du Bangladesh, en Asie du Sud.", "Région façonnée par le delta du Gange-Brahmapoutre et le golfe du Bengale.", "Climat tropical de mousson avec une alternance pluie/sécheresse.", "Accessible via le réseau routier et les voies navigables du delta.", "Imprégnée de l'héritage historique et culturel de la région bengalie.", "Le sud du pays est dominé par les mangroves des Sundarbans.", "L'économie repose sur la pêche, le textile, le jute et l'industrie navale."],
