     image: "/poi-images/faridpur-cities-v2.webp",
    descriptionAdvanced: {
      de: "Faridpur liegt im Zentrum von Bangladesch am Ufer des Flusses Padma und ist das administrative Herz des gleichnamigen Distrikts. Die Stadt wurde im Jahr 1815 gegründet und nach dem berühmten Sufi-Heiligen Schah Fariduddin Ganjshakar benannt, dessen Schrein ein bedeutendes spirituelles Ziel in der Region ist. Faridpur hat eine lange Tradition als Zentrum der Jute-Produktion und wird oft als einer der wichtigsten Knotenpunkte für den Handel mit dieser 'goldenen Faser' bezeichnet. Die Geografie der Stadt wird durch die Padma geprägt, was sie zu einem wichtigen Flusshafen für den Transport von Waren in den Süden des Landes macht. Historisch war Faridpur ein Geburtsort für viele prominente Politiker und Denker, darunter der Staatsgründer Scheich Mujibur Rahman, der im Distrikt geboren wurde. Die Architektur der Stadt zeigt eine Mischung aus kolonialen Gebäuden und modernen Strukturen. Heute ist Faridpur ein wichtiger Bildungsstandort mit mehreren medizinischen und technischen Hochschulen, die die Entwicklung der zentralen Region Bangladeschs vorantreiben.",
      hu: "Faridpur városa Banglades központi részén, a Padma-folyó partján fekszik, és a Faridpur körzet közigazgatási központja. Az 1815-ben alapított település nevét Shah Fariduddin Ganjshakar szúfi szentről kapta, akinek emléke ma is meghatározza a város vallási életét. A város történelmileg a juta-termesztés és kereskedelem fellegvára, amely jelentősen hozzájárult a régió gazdasági jólétéhez. Földrajzi elhelyezkedése a Padma partján fontos folyami kikötővé teszi, amely összeköti a központi területeket a déli országrésszel. Faridpur híres szülötteiről is, itt látta meg a napvilágot a nemzet atyja, Sheikh Mujibur Rahman is, akinek emlékezete mélyen gyökerezik a helyi közösségben. A város kulturális élete gazdag népművészeti hagyományokban, különösen a Baul zenében és a misztikus költészetben. Napjainkban Faridpur modern oktatási és egészségügyi központtá vált, amely kulcsszerepet játszik a környező mezőgazdasági vidékek fejlődésében.",
      ro: "Faridpur este un oraș istoric situat în centrul Bangladeshului, pe malul fluviului Padma, fiind reședința districtului cu același nume. Fondat în 1815, orașul a fost numit în onoarea sfântului sufit Shah Fariduddin Ganjshakar, al cărui mormânt este un loc de pelerinaj important. Localitatea este renumită la nivel mondial pentru calitatea iutei produse aici, fiind un nod comercial major pentru această fibră naturală esențială economiei naționale. Geografia orașului este influențată direct de fluviul Padma, care servește drept rută principală pentru transportul naval spre regiunile sudice. Faridpur are o importanță politică imensă, fiind regiunea de origine a lui Sheikh Mujibur Rahman, fondatorul națiunii Bangladesh. Orașul găzduiește numeroase clădiri din epoca colonială britanică, care coexistă cu noi centre medicale și academice moderne. În prezent, Faridpur continuă să se dezvolte ca un centru urban dinamic, susținând industria textilă și comerțul regional de tranzit.",
      en: "Faridpur is a historically significant city in central Bangladesh, situated on the banks of the Padma River and serving as the administrative capital of Faridpur District. Established in 1815, the city was named after the renowned Sufi saint Shah Fariduddin Ganjshakar, whose shrine remains a focal point for spiritual life in the area. Faridpur has long been celebrated as a premier center for jute production and trade, earning it a crucial role in the national economy. Its geography is defined by its proximity to the Padma, making it a vital river port for transporting goods across central and southern Bangladesh. The region holds immense political prestige as the birthplace of Sheikh Mujibur Rahman, the founding father of Bangladesh. Today, the city is a growing educational hub, featuring several medical colleges and technical institutes. With its blend of colonial architecture and modern infrastructure, Faridpur remains a key player in the commercial and cultural landscape of the country.",
      es: "Una ciudad antigua a orillas del río Padma, conocida por sus poetas, líderes espirituales y la producción de yute. Esto la convierte en uno de los puntos característicos de Bangladés en el delta del Ganges-Brahmaputra, en el golfo de Bengala y en los alrededores de los manglares de Sundarbans, ofreciendo una visión de la cultura bengalí, el monzón y la identidad regional. Situada en el estado de Bangladés, en el sur de Asia. Región caracterizada por el delta del Ganges-Brahmaputra y el golfo de Bengala. Clima monzónico tropical con marcadas estaciones lluviosa y seca.",
      pt: "Uma cidade antiga nas margens do rio Padma, conhecida pelos seus poetas, líderes espirituais e produção de juta. Isto torna o local num dos pontos característicos do Bangladexe no delta do Ganges-Brahmaputra, no golfo de Bengala e na envolvente dos mangais de Sundarbans, oferecendo uma visão da cultura bengali, da monção e da identidade regional. Localizada no estado do Bangladexe, no sul da Ásia. Região caracterizada pelo delta do Ganges-Brahmaputra e pelo golfo de Bengala. Clima tropical de monção com estações chuvosa e seca distintas.",
      fr: "Une ville ancienne sur les rives de la rivière Padma, connue pour ses poètes, ses guides spirituels et sa production de jute. Cela fait de ce lieu l'un des points caractéristiques du Bangladesh dans le delta du Gange-Brahmapoutre, dans le golfe du Bengale et dans les environs des mangroves des Sundarbans, offrant un aperçu de la culture bengalie, de la mousson et de l'identité régionale. Située dans l'État du Bangladesh, en Asie du Sud. Région marquée par le delta du Gange-Brahmapoutre et le golfe du Bengale. Climat de mousson tropicale avec des saisons des pluies et des saisons sèches marquées.",
    },
