      fr: ["Cette ville ferroviaire du Grand Nord relie le commerce à une population diversifiée venant de différentes régions d'Asie du Sud.", "Située dans l'État sud-asiatique du Bangladesh.", "Région marquée par le delta du Gange-Brahmapoutre et le golfe du Bengale.", "Climat tropical de mousson avec des saisons des pluies et sèches marquées.", "Accessible via le réseau routier et le vaste système fluvial du delta.", "Liée à l'héritage de la culture bengalie et du Bengale historique.", "Les Sundarbans, la plus grande forêt de mangroves au monde, marquent le sud du pays.", "Économie fortement marquée par les industries du textile, du jute et du transport maritime."],
