      pt: ["Grande produtor de bananas e vegetais", "Importante centro de têxteis tecidos à mão", "Abriga numerosas fábricas têxteis modernas", "Localização conveniente na estrada nacional Daca-Sylhet"],
      fr: ["Grand producteur de bananes et de légumes", "Centre important pour les textiles tissés à la main", "Abrite de nombreuses usines textiles modernes", "Idéalement située sur la route nationale Dhaka-Sylhet"],
