      fr: ["Pôle industriel proche de Dhaka spécialisé dans le textile et l'artisanat.", "Située dans l'État du Bangladesh, en Asie du Sud.", "Territoire façonné par le delta du Gange-Brahmapoutre et le golfe du Bengale.", "Climat tropical de mousson avec une alternance pluie/sécheresse.", "Desservie par le réseau routier et les voies navigables du delta.", "Imprégnée de l'héritage culturel et de l'histoire régionale bengalie.", "Les Sundarbans au sud forment la plus vaste mangrove du monde.", "Économie dynamique basée sur le textile, le jute et la navigation."],
