      es: ["Conocida como la ciudad Hilsa de Bangladés", "Importante puerto fluvial y centro comercial", "Famosa por el 'Mohana', la confluencia de tres ríos", "Centro del transporte fluvial regional"],
      pt: ["Conhecida como a cidade Hilsa do Bangladexe", "Importante porto fluvial e nó comercial", "Famosa pelo 'Mohana', a confluência de três rios", "Centro do tráfego de navegação interior regional"],
      fr: ["Connue comme la ville du Hilsa au Bangladesh", "Port fluvial et nœud commercial important", "Célèbre pour le 'Mohana', le confluent de trois rivières", "Centre du trafic de navigation intérieure régional"],
