      en: ["The largest island city in Bangladesh", "Ground zero for the catastrophic 1970 Bhola Cyclone", "Major hub for Hilsa fish and betel nut trade", "Home to significant newly discovered natural gas fields", "Located at the mouth of the Meghna River", "The district is known for its fertile alluvial soil and greenery"],
      es: ["La ciudad insular más grande del país se encuentra en el delta del Ganges y está rodeada de un rico paisaje natural fluvial.", "Situada en el estado sudasiático de Bangladés.", "Región marcada por el delta del Ganges-Brahmaputra y el golfo de Bengala.", "Clima monzónico tropical con estaciones seca y lluviosa marcadas.", "Accesible a través de la red de carreteras y el extenso sistema fluvial del delta.", "Vinculada al patrimonio de la cultura bengalí y de la Bengala histórica.", "Los Sundarbans, el bosque de manglares más grande del mundo, marcan el sur del país.", "Economía fuertemente influenciada por las industrias textil, del yute y naviera."],
      pt: ["A maior cidade insular do país situa-se no delta do Ganges e está rodeada por uma rica paisagem natural ribeirinha.", "Situa-se no estado sul-asiático do Bangladesh.", "Região marcada pelo delta do Ganges-Brahmaputra e pelo Golfo de Bengala.", "Clima de monção tropical com estações seca e chuvosa bem definidas.", "Acessível através da rede rodoviária e do extenso sistema fluvial do delta.", "Ligada à herança da cultura bengali e da Bengala histórica.", "Os Sundarbans, a maior floresta de mangais do mundo, marcam o sul do país.", "Economia fortemente influenciada pelas indústrias têxtil, de juta e naval."],
      fr: ["La plus grande ville insulaire du pays est située dans le delta du Gange et entourée d'un riche paysage fluvial naturel.", "Située dans l'État sud-asiatique du Bangladesh.", "Région marquée par le delta du Gange-Brahmapoutre et le golfe du Bengale.", "Climat de mousson tropicale avec des saisons des pluies et des saisons sèches marquées.", "Accessible par le réseau routier et le vaste système fluvial du delta.", "Liée à l'héritage de la culture bengalie et du Bengale historique.", "Les Sundarbans, la plus grande forêt de mangroves au monde, marquent le sud du pays.", "Économie fortement marquée par l'industrie textile, du jute et de la construction navale."],
